std::shared_ptr<SyncAuthenticator> FfiConverterSyncAuthenticator::lift(uint64_t handle) {
    // This interface can be implemented on either side of the FFI.
    // Rust makes its handles by leaking a pointer, so they are always even.
    if ((handle & 1) == 0) {
        return std::shared_ptr<SyncAuthenticator>(new SyncAuthenticatorImpl(handle));
    }

    auto impl = handle_map.at(handle);
    handle_map.erase(handle);

    return impl;
}

uint64_t FfiConverterSyncAuthenticator::lower(const std::shared_ptr<SyncAuthenticator> &obj) {
    // Rust values are instances of the generated implementation and own a handle we
    // can clone. Anything else is a C++ implementation of the trait.
    if (auto impl = std::dynamic_pointer_cast<SyncAuthenticatorImpl>(obj)) {
        return impl->_uniffi_internal_clone_handle();
    }

    // The trait is `WithForeign`, so Rust can call back through the vtable using a handle of
    // our own.
    return handle_map.insert(obj);
}

std::shared_ptr<SyncAuthenticator> FfiConverterSyncAuthenticator::read(RustStream &stream) {
    uint64_t ptr;
    stream >> ptr;

    return FfiConverterSyncAuthenticator::lift(ptr);
}

void FfiConverterSyncAuthenticator::write(RustStream &stream, const std::shared_ptr<SyncAuthenticator> &obj) {
    stream << FfiConverterSyncAuthenticator::lower(obj);
}

uint64_t FfiConverterSyncAuthenticator::allocation_size(const std::shared_ptr<SyncAuthenticator> &) {
    return 8;
}



