KeyRef FfiConverterKeyRef::read(RustStream &stream) {
    int32_t variant_id;
    stream >> variant_id;

    switch (variant_id) {
        
    case 1:
        return KeyRef::kUa {
            .seed = FfiConverterString::read(stream),
            .kind = FfiConverterUInt16::read(stream),
            .account = FfiConverterUInt32::read(stream),
            .index = FfiConverterUInt32::read(stream),
        };
        
    case 2:
        return KeyRef::kNative {
            .seed = FfiConverterString::read(stream),
            .network = FfiConverterString::read(stream),
            .index = FfiConverterUInt32::read(stream),
        };
        
    case 3:
        return KeyRef::kImported {
            .seed = FfiConverterString::read(stream),
            .network = FfiConverterString::read(stream),
            .index = FfiConverterUInt32::read(stream),
        };
        
    case 4:
        return KeyRef::kKey {
            .seed = FfiConverterString::read(stream),
            .id = FfiConverterString::read(stream),
        };
        
    case 5:
        return KeyRef::kMsig {
            .ua = FfiConverterString::read(stream),
            .slots = FfiConverterSequenceTypeMsigSlot::read(stream),
        };
        
    case 6:
        return KeyRef::kBlsMulti {
            .seed = FfiConverterString::read(stream),
            .account = FfiConverterUInt32::read(stream),
            .index = FfiConverterUInt32::read(stream),
            .key_data = FfiConverterString::read(stream),
        };
        
    case 7:
        return KeyRef::kSigned {
            .signer = FfiConverterString::read(stream),
        };
        
    default:
        throw std::runtime_error("No matching KeyRef variant");
    }
}

void FfiConverterKeyRef::write(RustStream &stream, const KeyRef &val) {
    int32_t variant_id = static_cast<int32_t>(val.variant.index() + 1);

    stream << variant_id;

    std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, KeyRef::kUa>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterUInt16::write(stream, arg.kind);
            FfiConverterUInt32::write(stream, arg.account);
            FfiConverterUInt32::write(stream, arg.index);
        }
        else if constexpr (std::is_same_v<T, KeyRef::kNative>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterString::write(stream, arg.network);
            FfiConverterUInt32::write(stream, arg.index);
        }
        else if constexpr (std::is_same_v<T, KeyRef::kImported>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterString::write(stream, arg.network);
            FfiConverterUInt32::write(stream, arg.index);
        }
        else if constexpr (std::is_same_v<T, KeyRef::kKey>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterString::write(stream, arg.id);
        }
        else if constexpr (std::is_same_v<T, KeyRef::kMsig>) {
            FfiConverterString::write(stream, arg.ua);
            FfiConverterSequenceTypeMsigSlot::write(stream, arg.slots);
        }
        else if constexpr (std::is_same_v<T, KeyRef::kBlsMulti>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterUInt32::write(stream, arg.account);
            FfiConverterUInt32::write(stream, arg.index);
            FfiConverterString::write(stream, arg.key_data);
        }
        else if constexpr (std::is_same_v<T, KeyRef::kSigned>) {
            FfiConverterString::write(stream, arg.signer);
        }
        else {
            static_assert(always_false_v<T>, "non-exhaustive KeyRef visitor");
        }
    }, val.variant);
}

