SlotKey FfiConverterSlotKey::lift(RustBuffer buf) {
    auto stream = RustStream(&buf);
    auto ret = FfiConverterSlotKey::read(stream);

    rustbuffer_free(buf);

    return std::move(ret);
}

RustBuffer FfiConverterSlotKey::lower(const SlotKey &val) {
    auto buf = rustbuffer_alloc(FfiConverterSlotKey::allocation_size(val));
    auto stream = RustStream(&buf);

    FfiConverterSlotKey::write(stream, val);

    return std::move(buf);
}

SlotKey FfiConverterSlotKey::read(RustStream &stream) {
    int32_t variant_id;
    stream >> variant_id;

    switch (variant_id) {
        
    case 1:
        return SlotKey::kUa {
            .seed = FfiConverterString::read(stream),
            .kind = FfiConverterUInt16::read(stream),
            .account = FfiConverterUInt32::read(stream),
            .index = FfiConverterUInt32::read(stream),
        };
        
    case 2:
        return SlotKey::kNative {
            .seed = FfiConverterString::read(stream),
            .network = FfiConverterString::read(stream),
            .index = FfiConverterUInt32::read(stream),
        };
        
    case 3:
        return SlotKey::kImported {
            .seed = FfiConverterString::read(stream),
            .network = FfiConverterString::read(stream),
            .index = FfiConverterUInt32::read(stream),
        };
        
    case 4:
        return SlotKey::kKey {
            .seed = FfiConverterString::read(stream),
            .id = FfiConverterString::read(stream),
        };
        
    case 5:
        return SlotKey::kMsig {
            .ua = FfiConverterString::read(stream),
        };
        
    case 6:
        return SlotKey::kBlsMulti {
            .seed = FfiConverterString::read(stream),
            .account = FfiConverterUInt32::read(stream),
            .index = FfiConverterUInt32::read(stream),
            .key_data = FfiConverterString::read(stream),
        };
        
    case 7:
        return SlotKey::kSigned {
            .signer = FfiConverterString::read(stream),
        };
        
    default:
        throw std::runtime_error("No matching SlotKey variant");
    }
}

void FfiConverterSlotKey::write(RustStream &stream, const SlotKey &val) {
    int32_t variant_id = static_cast<int32_t>(val.variant.index() + 1);

    stream << variant_id;

    std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, SlotKey::kUa>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterUInt16::write(stream, arg.kind);
            FfiConverterUInt32::write(stream, arg.account);
            FfiConverterUInt32::write(stream, arg.index);
        }
        else if constexpr (std::is_same_v<T, SlotKey::kNative>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterString::write(stream, arg.network);
            FfiConverterUInt32::write(stream, arg.index);
        }
        else if constexpr (std::is_same_v<T, SlotKey::kImported>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterString::write(stream, arg.network);
            FfiConverterUInt32::write(stream, arg.index);
        }
        else if constexpr (std::is_same_v<T, SlotKey::kKey>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterString::write(stream, arg.id);
        }
        else if constexpr (std::is_same_v<T, SlotKey::kMsig>) {
            FfiConverterString::write(stream, arg.ua);
        }
        else if constexpr (std::is_same_v<T, SlotKey::kBlsMulti>) {
            FfiConverterString::write(stream, arg.seed);
            FfiConverterUInt32::write(stream, arg.account);
            FfiConverterUInt32::write(stream, arg.index);
            FfiConverterString::write(stream, arg.key_data);
        }
        else if constexpr (std::is_same_v<T, SlotKey::kSigned>) {
            FfiConverterString::write(stream, arg.signer);
        }
        else {
            static_assert(always_false_v<T>, "non-exhaustive SlotKey visitor");
        }
    }, val.variant);
}

uint64_t FfiConverterSlotKey::allocation_size(const SlotKey &val) {
    uint64_t size = sizeof(int32_t);

    size += std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, SlotKey::kUa>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.seed);
            size += FfiConverterUInt16::allocation_size(arg.kind);
            size += FfiConverterUInt32::allocation_size(arg.account);
            size += FfiConverterUInt32::allocation_size(arg.index);
            return size;
        }
        else if constexpr (std::is_same_v<T, SlotKey::kNative>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.seed);
            size += FfiConverterString::allocation_size(arg.network);
            size += FfiConverterUInt32::allocation_size(arg.index);
            return size;
        }
        else if constexpr (std::is_same_v<T, SlotKey::kImported>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.seed);
            size += FfiConverterString::allocation_size(arg.network);
            size += FfiConverterUInt32::allocation_size(arg.index);
            return size;
        }
        else if constexpr (std::is_same_v<T, SlotKey::kKey>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.seed);
            size += FfiConverterString::allocation_size(arg.id);
            return size;
        }
        else if constexpr (std::is_same_v<T, SlotKey::kMsig>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.ua);
            return size;
        }
        else if constexpr (std::is_same_v<T, SlotKey::kBlsMulti>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.seed);
            size += FfiConverterUInt32::allocation_size(arg.account);
            size += FfiConverterUInt32::allocation_size(arg.index);
            size += FfiConverterString::allocation_size(arg.key_data);
            return size;
        }
        else if constexpr (std::is_same_v<T, SlotKey::kSigned>) {
            uint64_t size = 0;
            size += FfiConverterString::allocation_size(arg.signer);
            return size;
        }
        else {
            static_assert(always_false_v<T>, "non-exhaustive SlotKey visitor");
        }
    }, val.variant);

    return size;
}


