RustBuffer FfiConverterSource::lower(const Source &val) {
    auto buf = rustbuffer_alloc(FfiConverterSource::allocation_size(val));
    auto stream = RustStream(&buf);

    FfiConverterSource::write(stream, val);

    return std::move(buf);
}

Source FfiConverterSource::read(RustStream &stream) {
    int32_t variant;
    stream >> variant;

    switch (variant) {
        
    case 1:
        return Source::kSigned;
        
    case 2:
        return Source::kRequest;
        
    case 3:
        return Source::kDerived;
        
    default:
        throw std::runtime_error("No matching Source variant");
    }
}

void FfiConverterSource::write(RustStream &stream, const Source &val) {
    switch (val) {
        
    case Source::kSigned:
        stream << static_cast<int32_t>(1);
        break;
        
    case Source::kRequest:
        stream << static_cast<int32_t>(2);
        break;
        
    case Source::kDerived:
        stream << static_cast<int32_t>(3);
        break;
        
    default:
        throw std::runtime_error("No matching Source variant");
    }
}

uint64_t FfiConverterSource::allocation_size(const Source &) {
    return static_cast<uint64_t>(sizeof(int32_t));
}


