SubmitPath FfiConverterSubmitPath::read(RustStream &stream) {
    int32_t variant_id;
    stream >> variant_id;

    switch (variant_id) {
        
    case 1:
        return SubmitPath::kAuto {
            .payer = FfiConverterOptionalKeyRef::read(stream),
        };
        
    case 2:
        return SubmitPath::kGateway {
        };
        
    case 3:
        return SubmitPath::kSelfRelay {
            .payer = FfiConverterKeyRef::read(stream),
        };
        
    default:
        throw std::runtime_error("No matching SubmitPath variant");
    }
}

void FfiConverterSubmitPath::write(RustStream &stream, const SubmitPath &val) {
    int32_t variant_id = static_cast<int32_t>(val.variant.index() + 1);

    stream << variant_id;

    std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, SubmitPath::kAuto>) {
            FfiConverterOptionalKeyRef::write(stream, arg.payer);
        }
        else if constexpr (std::is_same_v<T, SubmitPath::kGateway>) {
        }
        else if constexpr (std::is_same_v<T, SubmitPath::kSelfRelay>) {
            FfiConverterKeyRef::write(stream, arg.payer);
        }
        else {
            static_assert(always_false_v<T>, "non-exhaustive SubmitPath visitor");
        }
    }, val.variant);
}

uint64_t FfiConverterSubmitPath::allocation_size(const SubmitPath &val) {
    uint64_t size = sizeof(int32_t);

    size += std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, SubmitPath::kAuto>) {
            uint64_t size = 0;
            size += FfiConverterOptionalKeyRef::allocation_size(arg.payer);
            return size;
        }
        else if constexpr (std::is_same_v<T, SubmitPath::kGateway>) {
            uint64_t size = 0;
            return size;
        }
        else if constexpr (std::is_same_v<T, SubmitPath::kSelfRelay>) {
            uint64_t size = 0;
            size += FfiConverterKeyRef::allocation_size(arg.payer);
            return size;
        }
        else {
            static_assert(always_false_v<T>, "non-exhaustive SubmitPath visitor");
        }
    }, val.variant);

    return size;
}


